/**
 * Golden Master media picker for the Sequence editor.
 *
 * Uses the WordPress media library so the administrator selects one confirmed
 * final image per variant. No frame sequence is uploaded.
 */
( function () {
	'use strict';

	if ( ! window.wp || ! window.wp.media ) {
		return;
	}

	var frames = {};

	function openPicker( variant, box ) {
		if ( ! frames[ variant ] ) {
			frames[ variant ] = window.wp.media( {
				title: box.getAttribute( 'data-shseq-picker-title' ) || 'Select Golden Master',
				button: { text: box.getAttribute( 'data-shseq-picker-button' ) || 'Use this image' },
				library: { type: 'image' },
				multiple: false
			} );

			frames[ variant ].on( 'select', function () {
				var attachment = frames[ variant ].state().get( 'selection' ).first().toJSON();
				var field = box.querySelector( '[data-shseq-master-field="' + variant + '"]' );
				var preview = box.querySelector( '[data-shseq-master-preview]' );
				if ( field ) {
					field.value = attachment.id;
				}
				if ( preview ) {
					var url = attachment.sizes && attachment.sizes.medium ? attachment.sizes.medium.url : attachment.url;
					preview.innerHTML = '';
					var img = document.createElement( 'img' );
					img.src = url;
					img.alt = '';
					preview.appendChild( img );
				}
			} );
		}

		frames[ variant ].open();
	}

	function clearMaster( variant, box ) {
		var field = box.querySelector( '[data-shseq-master-field="' + variant + '"]' );
		var preview = box.querySelector( '[data-shseq-master-preview]' );
		if ( field ) {
			field.value = '';
		}
		if ( preview ) {
			preview.innerHTML = '<span class="shseq-master-empty">' + ( preview.getAttribute( 'data-shseq-empty' ) || '' ) + '</span>';
		}
	}

	document.addEventListener( 'click', function ( event ) {
		var selectBtn = event.target.closest( '[data-shseq-master-select]' );
		if ( selectBtn && ! selectBtn.disabled ) {
			event.preventDefault();
			var variant = selectBtn.getAttribute( 'data-shseq-master-select' );
			var box = selectBtn.closest( '[data-shseq-variant]' );
			if ( box ) {
				openPicker( variant, box );
			}
			return;
		}

		var removeBtn = event.target.closest( '[data-shseq-master-remove]' );
		if ( removeBtn && ! removeBtn.disabled ) {
			event.preventDefault();
			var rVariant = removeBtn.getAttribute( 'data-shseq-master-remove' );
			var rBox = removeBtn.closest( '[data-shseq-variant]' );
			if ( rBox ) {
				clearMaster( rVariant, rBox );
			}
		}
	} );
}() );
